class Solution {
public:
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        vector<string> res;
        int n = words.size();
        int i = 0;
        while (i < n) {
            int j = i;
            int lineLen = 0;
            while (j < n && lineLen + (int)words[j].size() + (j - i) <= maxWidth) {
                lineLen += words[j].size();
                ++j;
            }
            int numWords = j - i;
            string line;
            if (j == n || numWords == 1) {
                for (int k = i; k < j; ++k) {
                    if (k > i) line += ' ';
                    line += words[k];
                }
                line += string(maxWidth - line.size(), ' ');
            } else {
                int gaps = numWords - 1;
                int totalSpaces = maxWidth - lineLen;
                vector<int> spaces(gaps, 1);
                int remaining = totalSpaces - gaps;
                int idx = 0;
                while (remaining-- > 0) {
                    spaces[idx]++;
                    idx = (idx + 1) % gaps;
                }
                for (int k = i; k < j - 1; ++k) {
                    line += words[k];
                    line += string(spaces[k - i], ' ');
                }
                line += words[j - 1];
            }
            res.push_back(line);
            i = j;
        }
        return res;
    }
};

