class Solution {
    public List<String> fullJustify(String[] words, int maxWidth) {
        List<String> res = new ArrayList<>();
        int n = words.length;
        int i = 0;
        while (i < n) {
            int j = i;
            int lineLen = 0;
            while (j < n && lineLen + words[j].length() + (j - i) <= maxWidth) {
                lineLen += words[j].length();
                j++;
            }
            int numWords = j - i;
            StringBuilder sb = new StringBuilder();
            if (j == n || numWords == 1) {
                for (int k = i; k < j; k++) {
                    if (k > i) sb.append(' ');
                    sb.append(words[k]);
                }
                while (sb.length() < maxWidth) sb.append(' ');
            } else {
                int gaps = numWords - 1;
                int totalSpaces = maxWidth - lineLen;
                int[] spaces = new int[gaps];
                for (int g = 0; g < gaps; g++) spaces[g] = 1;
                int remaining = totalSpaces - gaps;
                int idx = 0;
                while (remaining-- > 0) {
                    spaces[idx]++;
                    idx = (idx + 1) % gaps;
                }
                for (int k = i; k < j - 1; k++) {
                    sb.append(words[k]);
                    for (int s = 0; s < spaces[k - i]; s++) sb.append(' ');
                }
                sb.append(words[j - 1]);
            }
            res.add(sb.toString());
            i = j;
        }
        return res;
    }
}

